// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint256 deposit, uint256 amount, address actor) public {
        vm.assume(actor != address(c) && actor != address(0));
        deposit = bound(deposit, 1 ether + 1, 1000 ether);
        amount = bound(amount, 0, deposit);

        vm.deal(actor, deposit);
        vm.prank(actor);
        c.Deposit{value: deposit}();

        vm.prank(actor);
        c.CashOut(amount);

        // scan the public History getter for an entry recording this cash-out
        bool recorded = false;
        uint256 i = 0;
        while (i < 64) {
            try c.History(i) returns (address snd, string memory dat, uint256 val, uint256) {
                if (snd == actor && val == amount && keccak256(bytes(dat)) == keccak256(bytes("CashOut"))) {
                    recorded = true;
                    break;
                }
                i++;
            } catch {
                break;
            }
        }
        assertTrue(recorded);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Log lg;
    uint128 created;

    function setUp() public {
        uint128 nonce = created;
        c = new C(address(new Log()));
        lg = Log(_predictCreate1(address(this), uint64(nonce)));
        created += 2;
    }

    // Recovers the CREATE address of the Log deployed first in setUp()
    // (RLP: 0xd6 0x94 <origin> <nonceEnc>)
    function _predictCreate1(address origin, uint64 n) internal pure returns (address) {
        bytes memory nb;
        if (n == 0) {
            nb = hex"80";
        } else if (n <= 0x7f) {
            nb = abi.encodePacked(uint8(n));
        } else {
            uint len;
            uint t = n;
            while (t > 0) { len++; t >>= 8; }
            nb = new bytes(len + 1);
            nb[0] = bytes1(uint8(0x80 + len));
            for (uint i = 0; i < len; i++) {
                nb[len - i] = bytes1(uint8(uint(n) >> (8 * (len - 1 - i))));
            }
        }
        bytes memory buf = abi.encodePacked(bytes1(uint8(0xd6 + nb.length)), hex"d694", origin, nb);
        return address(uint160(uint256(keccak256(buf))));
    }

    // Number of History entries reachable through the log's public getter.
    function _histLen() internal returns (uint n) {
        for (uint i = 0; i < 50; i++) {
            try lg.History(i) returns (address, string memory, uint, uint) {
                n = i + 1;
            } catch {
                break;
            }
        }
    }

    function testFuzz_property(address actor, uint256 dep, uint256 amt) public {
        vm.assume(actor != address(c) && actor != address(lg) && actor != address(this));
        vm.assume(actor.code.length == 0);
        dep = bound(dep, 1.000001 ether, 1000 ether);

        // Deposit (succeeds because dep > MinDeposit)
        vm.deal(actor, dep);
        vm.prank(actor);
        c.Deposit{value: dep}();

        // Withdraw any amount up to the balance
        amt = bound(amt, 0, c.balances(actor));

        uint before = _histLen();
        vm.prank(actor);
        try c.CashOut(amt) {
            // rule: every successful cash-out appends exactly one History entry
            // Sender=actor, Data='CashOut', Val=amt
            uint afterL = _histLen();
            (address snd, string memory dat, uint256 val,) = lg.History(afterL - 1);
            assertTrue(
                afterL == before + 1 &&
                snd == actor &&
                keccak256(bytes(dat)) == keccak256(bytes("CashOut")) &&
                val == amt
            );
        } catch {
            // if cash-out reverted, the rule imposes nothing
            assertTrue(true);
        }
    }
}

